#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int current = 0; // start at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target = strtol(argv[i], &endptr, 10);
        // If conversion fails or extra characters, treat as invalid floor
        if (*endptr != '\0') {
            puts("INVALID_FLOOR");
            continue;
        }
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        if (target == current) {
            // No movement needed
            continue;
        }
        int step = (target > current) ? 1 : -1;
        while (current != target) {
            int next = current + step;
            if (step == 1) {
                printf("MOVE_UP %d->%d\n", current, next);
            } else {
                printf("MOVE_DOWN %d->%d\n", current, next);
            }
            current = next;
        }
        printf("ARRIVE %d\n", current);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current);
    return 0;
}
